import sys
import openpyxl

path = "budget.xlsx"
wb = openpyxl.load_workbook(path, data_only=False)
for name in wb.sheetnames:
    ws = wb[name]
    print(f"=== Sheet: {name} dims={ws.dimensions} max_row={ws.max_row} max_col={ws.max_column}")
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is not None:
                print(f"{cell.coordinate}: {repr(cell.value)}")

import openpyxl

wb = openpyxl.load_workbook("budget.xlsx", data_only=True)
ws = wb["Budget"]

expenses = []
for row in ws.iter_rows(min_row=11, max_row=22, min_col=1, max_col=3):
    cat, item, amt = row[0].value, row[1].value, row[2].value
    if amt is not None:
        expenses.append((cat, item, amt))

total = sum(x[2] for x in expenses)
cats = {}
for cat, item, amt in expenses:
    cats[cat] = cats.get(cat, 0) + amt

print("Items:")
for cat, item, amt in expenses:
    print(f"  {cat:15s} {item:15s} {amt}")
print(f"Total expenses (sum of items): {total}")
print("By category:")
for cat in sorted(cats):
    print(f"  {cat:15s} {cats[cat]}")
print(f"Sheet formula C23 value: {ws['C23'].value}")

